def compute(vars):
    termination_benefits = vars["v1"]
    total_restructuring_charges = vars["v2"]

    if total_restructuring_charges == 0:
        return None

    portion = termination_benefits / total_restructuring_charges
    return {
        "value": portion,
        "trace": {
            "termination_benefits": termination_benefits,
            "total_restructuring_charges": total_restructuring_charges,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": None
            }
        }
    }
